pair[] hex = new pair[6];
string[] hexlabels = {"$C$","$B$","$A$","$F$","$E$","$D$"};
hexlabels.cyclic=true;
hex[0] = dir(0);
for(int i = 1; i <= 6; ++i){

hex[i] = dir(60*i);

